import * as NodeModule from "node:module";
import { describe, expect, it } from "vite-plus/test";

const require = NodeModule.createRequire(import.meta.url);
const { addAudioSetup } = require("./withFriendVoiceReaderWebrtc.cjs");

// The relevant part of the MainApplication.kt generated by Expo SDK 58.
const MAIN_APPLICATION = `package com.t3tools.t3code.preview
import com.facebook.react.common.assets.ReactFontManager

import android.app.Application

class MainApplication : Application(), ReactApplication {
  override fun onCreate() {
    super.onCreate()
    loadReactNative(this)
  }
}`;

describe("withFriendVoiceReaderWebrtc", () => {
  it("installs the media-audio module before React Native loads", () => {
    const result = addAudioSetup(MAIN_APPLICATION);
    expect(result).toContain("import com.oney.WebRTCModule.WebRTCModuleOptions");
    expect(result.indexOf("AudioAttributes.USAGE_MEDIA")).toBeGreaterThan(
      result.indexOf("super.onCreate()"),
    );
    expect(result.indexOf("AudioAttributes.USAGE_MEDIA")).toBeLessThan(
      result.indexOf("loadReactNative(this)"),
    );
  });

  it("applies once across repeated prebuilds", () => {
    const once = addAudioSetup(MAIN_APPLICATION);
    expect(addAudioSetup(once)).toBe(once);
  });
});
